"use client";

import React from 'react';
import { AuthProvider } from '../context/AuthContext';
import { CartProvider } from '../context/CartContext';
import { CurrencyProvider } from '../context/CurrencyContext';

// This component acts as a bridge between the Server-Rendered Next.js layout 
// and the Client-Rendered context providers required for interactive features.
export default function ClientProviders({ children }) {
  return (
    <AuthProvider>
      <CurrencyProvider>
        <CartProvider>
          {children}
        </CartProvider>
      </CurrencyProvider>
    </AuthProvider>
  );
}
